package com.prudence.impact; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/impact") public class ImpactController {private final FriaRepository frias; public ImpactController(FriaRepository r){frias=r;} @PostMapping("/fria") public FriaJpaEntity fria(@RequestBody FriaBody b){if(!hash(b.dpiaSha256))throw new IllegalArgumentException("DPIA SHA-256 required");return frias.save(new FriaJpaEntity(UUID.randomUUID().toString(),b.aiSystemId,b.jurisdiction,b.templateVersion,b.affectedGroups,b.assumptions,b.mitigations,b.dpiaUri,b.dpiaSha256,b.signedBy,Instant.now().toString()));} private static boolean hash(String h){return h!=null&&h.replace("sha256:","").matches("[a-fA-F0-9]{64}");} public record FriaBody(String aiSystemId,String jurisdiction,String templateVersion,String affectedGroups,String assumptions,String mitigations,String dpiaUri,String dpiaSha256,String signedBy){} }
